def fizz_buzz(n: int):
    def count_occurrences(N: int, divisor: int) -> int:
        if N <= 0:
            return 0

        digits = list(map(int, str(N)))
        length = len(digits)

        @lru_cache(None)
        def dp(pos: int, remainder: int, tight: bool):
            if pos == length:
                return (1, 0) if remainder == 0 else (0, 0)

            limit = digits[pos] if tight else 9
            total_numbers = 0
            total_sevens = 0

            for digit in range(limit + 1):
