                total_numbers += child_numbers
                total_sevens += child_sevens
                if digit == 7:
                    total_sevens += child_numbers

            return total_numbers, total_sevens

        return dp(0, 0, True)[1]

    upper = n - 1
    return (
        count_occurrences(upper, 11)
        + count_occurrences(upper, 13)
        - count_occurrences(upper, 143)
