    end = min(interval1[1], interval2[1])

    # No intersection case
    if start > end:
        return "NO"

    length = end - start

    if length < 2:
        return "NO"

    # Check primality of length
    if length == 2:
        return "YES"
    if length % 2 == 0:
        return "NO"
    i = 3
