def closest_integer(value):
    from math import floor, ceil
    if value.count('.') == 1:
        # remove trailing zeros
        while value[-1] == '0':
            value = value[:-1]
    num = float(value)
    if value[-2:] == '.5':
        if num > 0:
            res = ceil(num)
        else:
            res = floor(num)
    else:
        num_floor = floor(num)
        if num - num_floor >= .5:
            res = num_floor + 1
        else:
            res = num_floor
    return int(res)
