def order_by_points(nums):
    """
    Sorts the given list of integers in ascending order according to
    the sum of their digits. For negative numbers, the first digit is
    treated as negative. Ties keep their original relative order.
    """
    def digit_sum(n):
        s = str(abs(n))
        if n < 0:
            total = -int(s[0])
            for ch in s[1:]:
                total += int(ch)
            return total
        return sum(int(ch) for ch in s)

    return sorted(nums, key=digit_sum)
